CREATE TABLE IF NOT EXISTS banners (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, title VARCHAR(180) NOT NULL, subtitle TEXT NULL, cta_text VARCHAR(80) NULL, cta_url VARCHAR(255) NULL, image_url VARCHAR(500) NULL, sort_order INT NOT NULL DEFAULT 0, status ENUM('active','draft') NOT NULL DEFAULT 'draft', starts_at DATETIME NULL, ends_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(id), INDEX idx_banners_status(status,sort_order));
INSERT INTO banners (title,subtitle,cta_text,cta_url,sort_order,status) SELECT 'استعداد مناسب برای ایده بزرگ بعدی شما','به متخصصان حرفه‌ای دسترسی پیدا کنید و پروژه‌تان را سریع‌تر جلو ببرید.','استخدام متخصص','/register?role=employer',1,'active' WHERE NOT EXISTS (SELECT 1 FROM banners);